package rhino.tests.mindustry;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static rhino.tests.mindustry.MindustryScripts.assertBoth;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.parallel.Isolated;
import rhino.Context;
import rhino.ContextFactory;
import rhino.JavaAdapter;

/**
 * JavaAdapter through {@link JavaAdapter#adapterFactory}, which iOS uses because it can't load
 * generated bytecode. {@link SubclassingAdapterFactory} plays the part of iOS's Subclasser.
 * Isolated, since the factory is global and would also serve tests running in parallel.
 */
@Isolated
class AdapterFactoryTest {
    private SubclassingAdapterFactory factory;

    @BeforeEach
    void install() {
        factory = new SubclassingAdapterFactory();
        JavaAdapter.adapterFactory = factory;
    }

    @AfterEach
    void uninstall() {
        JavaAdapter.adapterFactory = null;
    }

    @Test
    void interfaces() {
        assertBoth(
                "5,7",
                "var w = new JavaAdapter(F.WithDefault, {a(){ return 5; }, b(){ return 7; }});"
                        + "F.callA(w) + ',' + F.callB(w)");
        // default methods keep their implementation, also with the new Interface(){} syntax
        assertBoth("5,1", "var w = new F.WithDefault(){a: () => 5}; F.callA(w) + ',' + F.callB(w)");
        // other functions and data of the implementation object are reachable through this
        assertBoth(
                "7",
                "var w = new F.WithDefault({a(){ return this.helper() + this.k; }, helper(){ return 4; }, k: 3});"
                        + "F.callA(w)");
        // results are converted to the return types, arguments to JS values
        assertBoth(
                "2,true,1.5,7",
                "F.callPrim(new JavaAdapter(F.Prim, {i(){ return 2.9; }, z(){ return 1; }, f(){ return 1.5; }, s(){ return 7; }}))");
        assertBoth(
                "true,false",
                "var p = new java.util.function.Predicate(){test: v => v > 2}; p.test(3) + ',' + p.test(1)");
        assertBoth(
                "2",
                "var n = 0; var r = new java.lang.Runnable(){run: () => n++}; r.run(); r.run(); n");
        assertTrue(factory.createdClasses > 0);
    }

    @Test
    void classes() {
        assertBoth("q4", "extend(F.Base, 4, {name(){ return 'q'; }}).describe()");
        // the superclass constructor calls an override, which calls the superclass version
        assertBoth(
                "init+js,n3",
                "var e = extend(F.Base, 3, {name(){ return 'n'; }, init(){ this.super$init(); this.log += '+js'; }});"
                        + "e.log + ',' + e.describe()");
        assertBoth(
                "7,8",
                "var e = extend(F.Base, 1, {name(){ return 'n'; }, twice(v){ return this.super$twice(v) + 1; }});"
                        + "e.twice(3) + ',' + (e.twice(3) + e.x)");
        // fields set by extend() belong to each instance
        assertBoth(
                "aA1,bB2",
                "var a = extend(F.Base, 1, {name(){ return 'a' + this.tag; }, tag: 'A'});"
                        + "var b = extend(F.Base, 2, {name(){ return 'b' + this.tag; }, tag: 'B'});"
                        + "a.describe() + ',' + b.describe()");
        assertBoth("q9", "extend(F.Base, 4, {name(){ return 'q'; }, x: 9}).describe()");
        // fields hiding methods, and super$ for the hidden method
        assertBoth(
                "5,60",
                "var m = new JavaAdapter(F.Masked, { value(add){ return this.super$value(add) * 10; } });"
                        + "m.value + ',' + m.value(1)");
        assertTrue(factory.superCalls > 0);
    }

    @Test
    void classNamesAndCaching() {
        String name =
                MindustryScripts.eval(
                        new ContextFactory(),
                        Context.EvaluationMethod.Interpreter,
                        "var a = extend(F.Base, 1, {name(){ return 'a'; }});"
                                + "var b = extend(F.Base, 2, {name(){ return 'b'; }});"
                                + "F.typeOf(a) == F.typeOf(b) ? F.typeOf(a) : 'different classes'");
        // ScriptSandbox in Mindustry treats these names as their superclass
        assertTrue(name.startsWith(Fixtures.Base.class.getName() + "$JavaAdapter"), name);
        assertEquals(1, factory.createdClasses);
    }
}
